// Integration tests for stdlib/linalg/decomp

use linalg::decomp::*

fn test_abs(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    x
}

fn make_2x2(a00: f64, a01: f64, a10: f64, a11: f64) -> Matrix8 with Mut, Panic {
    var a = mat8_zeros(2, 2)
    a = mat8_set(a, 0, 0, a00)
    a = mat8_set(a, 0, 1, a01)
    a = mat8_set(a, 1, 0, a10)
    a = mat8_set(a, 1, 1, a11)
    a
}

fn make_3x3(
    a00: f64, a01: f64, a02: f64,
    a10: f64, a11: f64, a12: f64,
    a20: f64, a21: f64, a22: f64
) -> Matrix8 with Mut, Panic {
    var a = mat8_zeros(3, 3)
    a = mat8_set(a, 0, 0, a00)
    a = mat8_set(a, 0, 1, a01)
    a = mat8_set(a, 0, 2, a02)
    a = mat8_set(a, 1, 0, a10)
    a = mat8_set(a, 1, 1, a11)
    a = mat8_set(a, 1, 2, a12)
    a = mat8_set(a, 2, 0, a20)
    a = mat8_set(a, 2, 1, a21)
    a = mat8_set(a, 2, 2, a22)
    a
}

fn test_qr_identity() -> bool with Mut, Panic, Div {
