fn test_svd_sorted() -> bool with Mut, Panic, Div {
    let a = make_3x3(
        2.0, 1.0, 0.0,
        1.0, 3.0, 1.0,
        0.0, 1.0, 2.0
    )
    let result = svd_decompose(a)

    result.sigma[0] >= result.sigma[1] - 1.0e-10
        && result.sigma[1] >= result.sigma[2] - 1.0e-10
        && result.sigma[2] >= 0.0 - 1.0e-10
}

fn main() -> i32 with IO, Mut, Panic, Div {
    var passed = 0
    var failed = 0

    print("Test  1: QR identity............. ")
    if test_qr_identity() { println("PASS"); passed = passed + 1 }
