    var g1 = [0; 20]
    var g2 = [0; 20]
    var nsub = 0
    var a = 1
    while a <= 15 {
        var b = a + 1
        while b <= 15 {
            let ab = a ^ b
            var cc = b + 1
            while cc <= 15 {
                if cc != ab {
                    let ac = a ^ cc
                    let bc = b ^ cc
                    let abc = ab ^ cc
                    var mask = 0
                    mask = mask | (1 << a)
                    mask = mask | (1 << b)
                    mask = mask | (1 << ab)
                    mask = mask | (1 << cc)
                    mask = mask | (1 << ac)
                    mask = mask | (1 << bc)
                    mask = mask | (1 << abc)
                    var seen = 0
                    var t = 0
                    while t < nsub {
                        if masks[t as usize] == mask { seen = 1 }
                        t = t + 1
                    }
                    if seen == 0 {
                        masks[nsub as usize] = mask
                        g0[nsub as usize] = a
                        g1[nsub as usize] = b
                        g2[nsub as usize] = cc
                        nsub = nsub + 1
